// From the question:
//   Bottle objects are created by a constructor with a double parameter for
//   the bottle's capacity in millilitres, which is the maximum amount of
//   liquid it holds. Assume the value is greater than or equal to 0. Each
//   Bottle is filled to its capacity when it is constructed.
//
//   updateAmount has a double parameter for the amount of liquid to remove.
//   Its precondition is that the parameter is greater than zero and no larger
//   than the amount remaining. If the update would leave less than 25% of the
//   capacity, the bottle is filled and reset to the capacity. updateAmount
//   returns the amount remaining after the update.

modelSolution:
public class Bottle
{
    private double capacity;
    private double currentAmount;

    public Bottle(double start)
    {
        capacity = start;
        currentAmount = start;
    }

    public double updateAmount(double amountUsed)
    {
        currentAmount -= amountUsed;
        if (currentAmount < capacity * 0.25)
        {
            currentAmount = capacity;
        }
        return currentAmount;
    }
}

