public int moreHistoryThanMathAbsences()
{
    int count = 0;

    for (CourseRecord hst : historyList)
    {
        for (CourseRecord mth : mathList)
        {
            if (hst.getStudentID().equals(mth.getStudentID())
                    && hst.getAbsences() > mth.getAbsences())
            {
                count++;
            }
        }
    }
    return count;
}

